INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO-036','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Bezpieczniki na płytach','','description: Podobne elementy mogą pełnić różne funkcje. step: Nie zwieraj bezpieczników ani nie zastępuj ich drutem.','','',''),
('beginner:ZERO-037','beginner','Serwis i diagnostyka / Service & Diagnostics','Kondensatory','','description: Sam wygląd nie wystarcza do pewnej diagnozy. step: Nie dotykaj obwodów; wymianę elementów powierz technikowi.','','',''),
('beginner:ZERO-038','beginner','Serwis i diagnostyka / Service & Diagnostics','Filtry przeciwzakłóceniowe','','description: Filtry EMI ograniczają zakłócenia. step: Nie omijaj filtrów i nie rozbieraj zasilacza.','','',''),
('beginner:ZERO-039','beginner','Serwis i diagnostyka / Service & Diagnostics','Filtry powietrza i kurz','','description: Zabrudzone filtry ograniczają przepływ powietrza. step: Po odłączeniu zasilania wyczyść wyjmowany filtr zgodnie z instrukcją.','','',''),
('beginner:ZERO-040','beginner','Chłodzenie / Cooling','Wentylatory PWM','','description: PWM może regulować prędkość wentylatora. step: Sprawdź ustawienia UEFI; nie zatrzymuj łopatek ręką.','','',''),
('beginner:ZERO-041','beginner','Dyski i dane / Storage & Data','Nośnik instalacyjny USB','','description: Instalacja na złym dysku może usunąć dane. step: Przygotuj kopię i pobierz obraz systemu z oficjalnego źródła.','','',''),
('beginner:ZERO-042','beginner','Sprzęt i podzespoły / Hardware','Złośliwe oprogramowanie','','description: Spowolnienie nie dowodzi infekcji. step: Zaktualizuj system i uruchom zaufany skaner.','','',''),
('beginner:ZERO-043','beginner','Dyski i dane / Storage & Data','SMART i stan dysku','','description: Dane SMART mogą ostrzegać o problemach, ale nie gwarantują sprawności. step: Najpierw wykonaj kopię; sprawdź stan dysku narzędziem producenta.','','',''),
('beginner:ZERO-044','beginner','Serwis i diagnostyka / Service & Diagnostics','Tryb awaryjny','','description: Uruchamia system z ograniczonym zestawem sterowników. step: Zanotuj, czy problem występuje także w trybie awaryjnym.','','',''),
('beginner:ZERO-045','beginner','Obraz i ekran / Display','Monitor zewnętrzny','','description: Brak obrazu może wynikać z wejścia, przewodu lub ustawień. step: Sprawdź źródło sygnału monitora i inny kabel.','','',''),
('beginner:ZERO-046','beginner','Obraz i ekran / Display','Przewody obrazu HDMI i DisplayPort','','description: Przewód i adapter muszą obsługiwać wymagany sygnał. step: Sprawdź zgodność złączy i wybierz właściwe wejście monitora.','','',''),
('beginner:ZERO-047','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Ochrona ESD','','description: Wyładowania elektrostatyczne mogą uszkodzić elektronikę. step: Odłącz zasilanie i stosuj zasady ochrony ESD przy pracy z podzespołami.','','',''),
('beginner:ZERO-048','beginner','Zasilanie / Power','Zasilacz awaryjny UPS','','description: UPS daje czas na zapisanie pracy, nie zastępuje kopii danych. step: Sprawdź moc obciążenia i instrukcję UPS; nie otwieraj jego obudowy.','','',''),
('beginner:ZERO-049','beginner','System i sterowniki / System & Drivers','Rejestr systemowy','','description: Błędne zmiany konfiguracji mogą unieruchomić system. step: Przed zmianami zrób kopię i udokumentuj dotychczasowe ustawienia.','','',''),
('beginner:ZERO-050','beginner','BIOS i rozruch / BIOS & Boot','Aktualizacje firmware','','description: Przerwana aktualizacja firmware może utrudnić uruchomienie urządzenia. step: Sprawdź dokładny model i instrukcję producenta; zapewnij stabilne zasilanie.','','',''),
('beginner:ZERO-051','beginner','Serwis i diagnostyka / Service & Diagnostics','Testowanie po naprawie','','description: Pojedyncze uruchomienie nie potwierdza usunięcia usterki. step: Powtórz wcześniejszy scenariusz problemu i sprawdź pliki oraz temperatury.','','',''),
('beginner:ZERO-052','beginner','Serwis i diagnostyka / Service & Diagnostics','Zalanie komputera','','description: Podłączanie zalanego sprzętu może pogłębić uszkodzenia. step: Odłącz zasilanie, nie ładuj urządzenia i skonsultuj je z serwisem.','','',''),
('beginner:ZERO-053','beginner','Serwis i diagnostyka / Service & Diagnostics','Kiedy oddać sprzęt do serwisu','','description: Dym, spuchnięta bateria i praca przy napięciu wymagają specjalisty. step: Przerwij pracę i opisz objawy bez ponownego uruchamiania sprzętu.','','',''),
('beginner:ZERO-054','beginner','Serwis i diagnostyka / Service & Diagnostics','Komputer nie reaguje na przycisk','','description: Brak reakcji nie wskazuje jednoznacznie uszkodzonej płyty głównej. step: Sprawdź zewnętrzne zasilanie i zanotuj, czy świecą kontrolki.','','',''),
('beginner:ZERO-055','beginner','Serwis i diagnostyka / Service & Diagnostics','Komputer włącza się i gaśnie','','description: Powtarzające się wyłączanie może mieć kilka przyczyn, w tym przegrzewanie. step: Zapisz czas do wyłączenia i nie uruchamiaj urządzenia wielokrotnie na siłę.','','',''),
('beginner:ZERO-056','beginner','Obraz i ekran / Display','Czarny ekran po uruchomieniu','','description: Przyczyną może być monitor, wyjście obrazu albo etap uruchamiania. step: Sprawdź kontrolki monitora, wybrane wejście i komunikaty POST.','','',''),
('beginner:ZERO-057','beginner','Obraz i ekran / Display','Niebieski ekran i kody błędów','','description: Kod błędu pomaga zawęzić problem, ale nie wskazuje zawsze jednego podzespołu. step: Zapisz dokładny kod i moment wystąpienia; sprawdź kopię danych.','','',''),
('beginner:ZERO-058','beginner','BIOS i rozruch / BIOS & Boot','Powolny start systemu','','description: Długi rozruch może wiązać się z dyskiem, aktualizacjami lub programami startowymi. step: Sprawdź wolne miejsce i stan kopii zapasowej przed dalszą diagnostyką.','','',''),
('beginner:ZERO-059','beginner','Dyski i dane / Storage & Data','Brak miejsca na dysku','','description: Pełny dysk utrudnia aktualizacje i normalną pracę systemu. step: Sprawdź, co zajmuje miejsce; nie usuwaj nieznanych folderów systemowych.','','',''),
('beginner:ZERO-060','beginner','Dyski i dane / Storage & Data','SSD SATA a NVMe','','description: Nośniki mogą różnić się złączem, protokołem i obsługą przez komputer. step: Przed zakupem sprawdź dokumentację gniazda i rozmiar nośnika.','','',''),
('beginner:ZERO-061','beginner','Sprzęt i podzespoły / Hardware','Zgodność podzespołów','','description: Samo dopasowanie wtyku nie gwarantuje zgodności. step: Porównaj specyfikacje płyty, procesora, RAM i zasilania przed zakupem.','','',''),
('beginner:ZERO-062','beginner','Serwis i diagnostyka / Service & Diagnostics','Dziennik objawów','','description: Chronologia zmian ułatwia odróżnienie przyczyny od przypadku. step: Zapisz objaw, datę, ostatnie zmiany i wyniki każdej bezpiecznej próby.','','',''),
('beginner:ZERO-063','beginner','Serwis i diagnostyka / Service & Diagnostics','Diagnostyka po jednej zmianie','','description: Jednoczesna zmiana kilku ustawień utrudnia ustalenie, co pomogło. step: Wprowadzaj jedną odwracalną zmianę naraz i notuj wynik.','','',''),
('beginner:ZERO-064','beginner','System i sterowniki / System & Drivers','Punkty przywracania systemu','','description: Przywracanie ustawień nie zastępuje kopii osobistych plików. step: Przed użyciem sprawdź zakres zmian oraz wykonaj kopię ważnych danych.','','',''),
('beginner:ZERO-065','beginner','System i sterowniki / System & Drivers','Aktualizacje systemu','','description: Aktualizacje mogą naprawiać błędy, ale wymagają czasu i wolnego miejsca. step: Zabezpiecz dane, zapewnij zasilanie i użyj oficjalnego mechanizmu aktualizacji.','','',''),
('beginner:ZERO-066','beginner','Dyski i dane / Storage & Data','Uprawnienia aplikacji','','description: Brak dostępu do kamery lub mikrofonu może wynikać z ustawień prywatności. step: Sprawdź uprawnienia konkretnej aplikacji, zanim uznasz sprzęt za zepsuty.','','',''),
('beginner:ZERO-067','beginner','Sieć i internet / Network','DNS i dostęp do stron','','description: Działający internet nie zawsze oznacza poprawne rozwiązywanie nazw stron. step: Porównaj kilka stron i inne urządzenie w tej samej sieci.','','',''),
('beginner:ZERO-068','beginner','Sieć i internet / Network','Słaby sygnał Wi-Fi','','description: Odległość, przeszkody i zakłócenia mogą pogarszać połączenie. step: Porównaj działanie bliżej routera; nie zmieniaj naraz wielu ustawień sieci.','','',''),
('beginner:ZERO-069','beginner','Serwis i diagnostyka / Service & Diagnostics','Hotspot telefonu','','description: Hotspot pomaga sprawdzić, czy trudność dotyczy domowej sieci. step: Połącz komputer z własnym hotspotem i porównaj zachowanie; pamiętaj o limicie danych.','','',''),
('beginner:ZERO-070','beginner','Peryferia / Peripherals','Złącza i adaptery USB-C','','description: Ten sam kształt złącza może oznaczać różne możliwości. step: Sprawdź specyfikację komputera, adaptera i kabla.','','','');
